examples.template:
MonarchShiftRoster(
    members: [
        MonarchShiftRosterMember(id: {{members.0.id}}, name: {{members.0.name}}, description: {{members.0.description}}),
        MonarchShiftRosterMember(id: {{members.1.id}}, name: {{members.1.name}}, description: {{members.1.description}}),
        MonarchShiftRosterMember(id: {{members.2.id}}, name: {{members.2.name}}, description: {{members.2.description}}),
    ],
    shifts: [
        MonarchShiftRosterShift(id: {{shifts.0.id}}, name: {{shifts.0.name}}, start: {{shifts.0.start}}, end: {{shifts.0.end}}, shortName: {{shifts.0.shortName}}, color: Color(red: {{shifts.0.color.r}} / 255.0, green: {{shifts.0.color.g}} / 255.0, blue: {{shifts.0.color.b}} / 255.0)),
        MonarchShiftRosterShift(id: {{shifts.1.id}}, name: {{shifts.1.name}}, start: {{shifts.1.start}}, end: {{shifts.1.end}}, color: Color(red: {{shifts.1.color.r}} / 255.0, green: {{shifts.1.color.g}} / 255.0, blue: {{shifts.1.color.b}} / 255.0)),
        MonarchShiftRosterShift(id: {{shifts.2.id}}, name: {{shifts.2.name}}, start: {{shifts.2.start}}, end: {{shifts.2.end}}, color: Color(red: {{shifts.2.color.r}} / 255.0, green: {{shifts.2.color.g}} / 255.0, blue: {{shifts.2.color.b}} / 255.0)),
    ],
    from: {{from|date}},
    value: $roster,
    layout: .grid,
    today: {{today|date}},
    calendar: {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
        calendar.locale = Locale(identifier: {{locale}})
        return calendar
    }(),
    uses24HourClock: true,
    onChange: { change in
        // The app saves change.memberId, change.day and change.assignment here.
        _ = change
    }
)

